head.script:
//발행기관
scwin.vScrenID = "ULDINS90400.xml";

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    //$c.libRoundPanel.PanelToGroupBox(panel_2);    //불필요삭제

    //ELS/DLS 관리 : 신청과 동일한 발행기관만 출력( 20140327 : 박지은 대리 요쳥)
    //var sd = $c.frame.path("../").scwin.vScrenID; //변경
    const sd = $p.parent().scwin.vScrenID; //변경

    if (sd === "ULDINS15200.xml") {
        //ELS/DLS 관리
        txb_WRNT_ISUR_CD_YN.setValue("Y");
    }
    txb_ISUR_NM.focus();
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    const ISUR_CD = dtl_ListRes.getCellData(row, "ISUR_CD");
    const COM_NM = dtl_ListRes.getCellData(row, "COM_NM");
    const BENFCERT_ISUR_CD = dtl_ListRes.getCellData(row, "BENFCERT_ISUR_CD");

    //----W-Craft WebSquare 변환 확인: ins_popupRtn_cdnm----//
    //$c.frame.path("../").ins_popupRtn_cdnm(ISUR_CD, COM_NM);    //변경
    $c.cm.ins_popupRtn_cdnm(ISUR_CD, COM_NM);    //변경
    if ($c.frame.path("../").scwin.vScrenID === "ULDINS91600.xml") {
        $c.frame.path("../").ins_search();
    }

    //alert(frame.Provider("../").txb_ISUR_CD.value);
    //2016.11.02  선납금 등록 추가
    if ($c.frame.path("../").scwin.vScrenID === "ULDINS21302.xml") {

        //----W-Craft WebSquare 변환 확인: fn_listPrepayChg----//
        $c.frame.path("../").fn_listPrepayChg(ISUR_CD, COM_NM);
    }

    //2016.11.23  선납금 조회 추가
    if ($c.frame.path("../").scwin.vScrenID === "ULDINS21300.xml") {

        //----W-Craft WebSquare 변환 확인: fn_listPrepayChg----//
        $c.frame.path("../").fn_listPrepayChg(); //선납금목록조회

        //----W-Craft WebSquare 변환 확인: fn_readPrepayChg----//
        $c.frame.path("../").fn_readPrepayChg(); //선납잔액조회

    }
    await $c.win.closePopup();
};

scwin.btn_close_onclick = function() {
    $c.win.closePopup();
};

scwin.btn_search_onclick = function() {
    scwin.ins_search(txb_ISUR_NM.getValue());
};

scwin.dtl_ListRes_OnLoadCompleted = async function(responseJSON) {
    if (responseJSON.errors) {
        $c.win.alert(responseJSON.errors);
    } else {
        let rowcount = responseJSON.body.length;
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }

};

scwin.dtl_ListRes_OnLoadError = function() {
    $c.win.alert(dtl_ListRes);

};

scwin.txb_ISUR_NM_onkeyup = function(e) {

    //----W-Craft WebSquare 변환 확인: fn_DelChar3----//
    $c.cm.fn_DelChar3(this);
    if (txb_ISUR_NM.getValue() === "") {

    } else {
        if (e.keyCode === 13) {
            scwin.ins_search(txb_ISUR_NM.getValue());
        } else {

        }
    }
};

scwin.grd_Grid_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    scwin.grd_Grid_OnDblClick(rowIndex, columnId);
};

